# expected columns: WEO Country Code, ISO, Country, Subject Code etc
# locate indices by name
col_index={name:None for name in ['WEO Country Code','Country','WEO Subject Code']}
for c,v in enumerate(hdr, start=1):
    if v in col_index:
        col_index[v]=c
