targets={('Georgia','NGDP_R'):None, ('Georgia','NGDP_RPCH'):None}
for r in range(2, ws.max_row+1):
    country=ws.cell(r,col_index['Country']).value
    if country!='Georgia':
        continue
    subj=ws.cell(r,col_index['WEO Subject Code']).value
    if (country,subj) in targets and targets[(country,subj)] is None:
