    if isinstance(v,int) and 1990<=v<=2050:
        year_cols[v]=c
print('min year', min(year_cols), 'max year', max(year_cols), 'count', len(year_cols))
# find rows for Georgia codes
# expected columns: WEO Country Code, ISO, Country, Subject Code etc
# locate indices by name
col_index={name:None for name in ['WEO Country Code','Country','WEO Subject Code']}
for c,v in enumerate(hdr, start=1):
    if v in col_index:
        col_index[v]=c
print('col_index', col_index)
# iterate rows to find Georgia & subject
targets={('Georgia','NGDP_R'):None, ('Georgia','NGDP_RPCH'):None}
for r in range(2, ws.max_row+1):
    country=ws.cell(r,col_index['Country']).value
    if country!='Georgia':
        continue
    subj=ws.cell(r,col_index['WEO Subject Code']).value
    if (country,subj) in targets and targets[(country,subj)] is None:
        targets[(country,subj)]=r
        print('found', country, subj, 'row', r)
        if all(targets.values()):
            break
print('targets', targets)
# output sample values
for key,row in targets.items():
    if not row: continue
    vals={y: ws.cell(row, year_cols[y]).value for y in range(2000,2028)}
    print(key, list(vals.items())[:5], '...', list(vals.items())[-3:])
