needed=['countrycode','year','rnna','delta']
for n in needed:
    if n not in col:
        raise RuntimeError(f'Missing {n} in PWT headers')

data_rnna={}
data_delta={}
for row in ws.iter_rows(min_row=2, values_only=True):
    ccode=row[col['countrycode']-1]
    if ccode!='GEO':
        continue
    year=row[col['year']-1]
    if year is None:
        continue
    year=int(year)
    if 1990<=year<=2023:
        data_rnna[year]=row[col['rnna']-1]
        data_delta[year]=row[col['delta']-1]

ws_pwt['B1'].value='rnna'
ws_pwt['C1'].value='delta'
for r in range(2,36):
    year=ws_pwt.cell(r,1).value
    if year in data_rnna:
        ws_pwt.cell(r,2).value=float(data_rnna[year]) if data_rnna[year] is not None else None
        ws_pwt.cell(r,3).value=float(data_delta[year]) if data_delta[year] is not None else None

# ------------------ STEP 1B: WEO data (Georgia) ------------------
weo_csv='/tmp/WEOApr2025all.csv'
try:
    open(weo_csv,'rb').close()
except FileNotFoundError:
    xls='/tmp/WEOApr2025all.xls'
    urllib.request.urlretrieve('https://www.imf.org/-/media/Files/Publications/WEO/WEO-Database/2025/April/WEOApr2025all.xls', xls)
    import subprocess
    subprocess.check_call(['libreoffice','--headless','--convert-to','csv','--outdir','/tmp', xls])

with open(weo_csv,'r',encoding='utf-8',errors='ignore') as f:
    header=f.readline().rstrip('\n')
cols=header.split('\t')
idx_country=cols.index('Country')
idx_subj=cols.index('WEO Subject Code')
year_idx={}
for i,c in enumerate(cols):
    try:
        y=int(c)
        year_idx[y]=i
    except:
        pass

def parse_num(x):
    if x is None:
        return None
    x=str(x).strip()
    if x in ('n/a',''):
        return None
    x=x.replace(',','')
    try:
        return float(x)
    except:
        return None

series=defaultdict(dict)
found=set()
with open(weo_csv,'r',encoding='utf-8',errors='ignore') as f:
    next(f)
    for line in f:
        if not line.strip():
            continue
        parts=line.rstrip('\n').split('\t')
        if len(parts)<=max(idx_country,idx_subj):
            continue
        if parts[idx_country] != 'Georgia':
            continue
        subj=parts[idx_subj]
        if subj not in ('NGDP_R','NGDP_RPCH'):
            continue
        for y in range(2000,2028):
            series[subj][y]=parse_num(parts[year_idx[y]])
        found.add(subj)
        if found=={'NGDP_R','NGDP_RPCH'}:
            break

# Map years to rows in template
year_to_row={}
for r in range(8,100):
    y=ws_weo.cell(r,2).value
    if isinstance(y,int):
        year_to_row[y]=r
    else:
        break

for y in range(2000,2028):
    r=year_to_row.get(y)
    if r:
        ws_weo.cell(r,3).value=series['NGDP_R'].get(y)
        ws_weo.cell(r,4).value=series['NGDP_RPCH'].get(y)

row_2027=year_to_row[2027]
for y in range(2028,2044):
    r=year_to_row.get(y)
    if not r:
        continue
    ws_weo.cell(r,4).value=f'=$D${row_2027}'
    prev_r=year_to_row[y-1]
    ws_weo.cell(r,3).value=f'=C{prev_r}*(1+D{r}/100)'

# ------------------ STEP 1C: ECB CFC series ------------------
ecb_url='https://data-api.ecb.europa.eu/service/data/IDCM/A.N.GE.W2.S1.S1.D.P51C.N1G._T._Z.XDC.V.N?format=csvdata'
ecb_csv='/tmp/ecb_cfc.csv'
urllib.request.urlretrieve(ecb_url, ecb_csv)

y_to_cfc={}
with open(ecb_csv,'r',encoding='utf-8',errors='ignore') as f:
    reader=csv.DictReader(f)
    for row in reader:
        y=int(row['TIME_PERIOD'])
        y_to_cfc[y]=float(row['OBS_VALUE']) if row['OBS_VALUE'] else None

for r in range(2,30):
    y=ws_cfc.cell(r,2).value
    if isinstance(y,int) and y in y_to_cfc:
        ws_cfc.cell(r,3).value=y_to_cfc[y]
    ws_cfc.cell(r,4).value=f'=INDEX(PWT!$B$2:$B$35,MATCH(B{r},PWT!$A$2:$A$35,0))'
    ws_cfc.cell(r,5).value=f'=C{r}/D{r}'

ws_prod['B3'].value="=AVERAGE('CFC data'!E22:E29)"

# ------------------ STEP 2: Link data to Production and compute LnK/LnY/LnZ ------------------
alpha_cell='$B$2'
for r in range(6,28):
    year=ws_prod.cell(r,3).value
    if not isinstance(year,int):
        continue
    ws_prod.cell(r,4).value=f'=INDEX(PWT!$B$2:$B$35,MATCH(C{r},PWT!$A$2:$A$35,0))'
    ws_prod.cell(r,5).value=f'=INDEX(WEO_Data!$C$8:$C$51,MATCH(C{r},WEO_Data!$B$8:$B$51,0))'
    ws_prod.cell(r,6).value=f'=LN(D{r})'
    ws_prod.cell(r,7).value=f'=LN(E{r})'
    ws_prod.cell(r,11).value=f'=G{r}-{alpha_cell}*F{r}'

# HP filter helper columns
for r in range(6,28):
    ws_prod.cell(r,14).value=f'=K{r}-L{r}'
for r in range(8,28):
    ws_prod.cell(r,13).value=f'=L{r}-2*L{r-1}+L{r-2}'
ws_prod['P5'].value='=SUMSQ(N6:N27)+100*SUMSQ(M8:M27)'

# ------------------ HP filter compute (lambda=100) ------------------
lam=100.0
alpha=ws_prod['B2'].value

# build data maps for direct numeric computation
pwt_rnna={ws_pwt.cell(r,1).value: ws_pwt.cell(r,2).value for r in range(2,36)}
# For WEO Y, only numeric years 2000-2027 are values; our 2028+ are formulas but we don't need for HP filter.
weo_y={}
for y in range(2000,2028):
    r=year_to_row[y]
    weo_y[y]=ws_weo.cell(r,3).value

years=[ws_prod.cell(r,3).value for r in range(6,28)]
y=[math.log(weo_y[yr]) - alpha*math.log(pwt_rnna[yr]) for yr in years]
T=len(y)

# Build A = I + lam * D'D using outer products
A=[[0.0]*T for _ in range(T)]
for i in range(T):
    A[i][i]=1.0

for k in range(T-2):
    idx=[k,k+1,k+2]
    d=[1.0,-2.0,1.0]
    for i_i,ii in enumerate(idx):
        for j_j,jj in enumerate(idx):
            A[ii][jj] += lam*d[i_i]*d[j_j]

# Solve A x = y (Gaussian elimination with partial pivot)
# Make augmented matrix
M=[A[i][:] + [y[i]] for i in range(T)]

for col_i in range(T):
    # pivot
    pivot=col_i
    maxabs=abs(M[col_i][col_i])
    for r in range(col_i+1,T):
        if abs(M[r][col_i])>maxabs:
            maxabs=abs(M[r][col_i])
            pivot=r
    if maxabs==0:
        raise RuntimeError('Singular matrix in HP filter')
    if pivot!=col_i:
        M[col_i],M[pivot]=M[pivot],M[col_i]
    # normalize pivot row
    pv=M[col_i][col_i]
    for c in range(col_i, T+1):
        M[col_i][c]/=pv
    # eliminate below
    for r in range(col_i+1,T):
        factor=M[r][col_i]
        if factor==0:
            continue
        for c in range(col_i, T+1):
            M[r][c] -= factor*M[col_i][c]

x=[0.0]*T
for i in range(T-1,-1,-1):
    x[i]=M[i][T] - sum(M[i][j]*x[j] for j in range(i+1,T))

# Write trend values to L6:L27
for i,r in enumerate(range(6,28)):
    ws_prod.cell(r,12).value=float(x[i])

# ------------------ STEP 3: Production function table ------------------
anchor_range='$D$49:$D$57'
for r in range(36,76):
    # Y
    ws_prod.cell(r,6).value=f'=INDEX(WEO_Data!$C$8:$C$51,MATCH(C{r},WEO_Data!$B$8:$B$51,0))'

for r in range(36,58):
    ws_prod.cell(r,5).value=f'=INDEX(PWT!$B$2:$B$35,MATCH(C{r},PWT!$A$2:$A$35,0))'
for r in range(58,76):
    ws_prod.cell(r,5).value=f'=AVERAGE({anchor_range})*F{r}'

for r in range(36,76):
    ws_prod.cell(r,4).value=f'=E{r}/F{r}'

for r in range(36,58):
    ws_prod.cell(r,7).value=f'=INDEX($L$6:$L$27,MATCH(C{r},$C$6:$C$27,0))'
for r in range(58,76):
    ws_prod.cell(r,7).value=f'=TREND($G$36:$G$57,$C$36:$C$57,C{r})'

for r in range(36,76):
    ws_prod.cell(r,8).value=f'=EXP(G{r}+{alpha_cell}*LN(E{r}))'
    ws_prod.cell(r,9).value=f'=IFERROR(VLOOKUP(C{r},Investment!$B$2:$C$9,2,FALSE),0)'

for r in range(36,76):
    year=ws_prod.cell(r,3).value
    if year<=2025:
        ws_prod.cell(r,10).value=0
    else:
        ws_prod.cell(r,10).value=f'=(1-$B$3)*J{r-1}+I{r}'

for r in range(36,76):
    ws_prod.cell(r,11).value=f'=E{r}+J{r}'
    ws_prod.cell(r,12).value=f'=EXP(G{r}+{alpha_cell}*LN(K{r}))'
    ws_prod.cell(r,13).value=f'=L{r}-H{r}'
    ws_prod.cell(r,14).value=f'=F{r}+M{r}'

# Growth rates
ws_prod.cell(36,15).value=None
ws_prod.cell(36,16).value=None
for r in range(37,76):
    ws_prod.cell(r,15).value=f'=(N{r}/N{r-1}-1)*100'
    ws_prod.cell(r,16).value=f'=(F{r}/F{r-1}-1)*100'

# Save
wb.save(wb_path)
print('Updated', wb_path)
