    pivot=col_i
    maxabs=abs(M[col_i][col_i])
    for r in range(col_i+1,T):
        if abs(M[r][col_i])>maxabs:
            maxabs=abs(M[r][col_i])
            pivot=r
    if maxabs==0:
        raise RuntimeError('Singular matrix in HP filter')
    if pivot!=col_i:
        M[col_i],M[pivot]=M[pivot],M[col_i]
    # normalize pivot row
    pv=M[col_i][col_i]
    for c in range(col_i, T+1):
        M[col_i][c]/=pv
    # eliminate below
    for r in range(col_i+1,T):
        factor=M[r][col_i]
        if factor==0:
            continue
        for c in range(col_i, T+1):
            M[r][c] -= factor*M[col_i][c]

x=[0.0]*T
for i in range(T-1,-1,-1):
    x[i]=M[i][T] - sum(M[i][j]*x[j] for j in range(i+1,T))

# Write trend values to L6:L27
for i,r in enumerate(range(6,28)):
    ws_prod.cell(r,12).value=float(x[i])

# ------------------ STEP 3: Production function table ------------------
anchor_range='$D$49:$D$57'
for r in range(36,76):
