    else:
        ws_prod.cell(r,10).value=f'=(1-$B$3)*J{r-1}+I{r}'

for r in range(36,76):
    ws_prod.cell(r,11).value=f'=E{r}+J{r}'
    ws_prod.cell(r,12).value=f'=EXP(G{r}+{alpha_cell}*LN(K{r}))'
    ws_prod.cell(r,13).value=f'=L{r}-H{r}'
    ws_prod.cell(r,14).value=f'=F{r}+M{r}'

# Growth rates
ws_prod.cell(36,15).value=None
ws_prod.cell(36,16).value=None
for r in range(37,76):
    ws_prod.cell(r,15).value=f'=(N{r}/N{r-1}-1)*100'
    ws_prod.cell(r,16).value=f'=(F{r}/F{r-1}-1)*100'

# Save
wb.save(wb_path)
print('Updated', wb_path)
